CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE public."AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id")
);

CREATE TABLE public."AspNetRoles" (
    "Id" text NOT NULL,
    "Name" text,
    "NormalizedName" text,
    "ConcurrencyStamp" text,
    "Discriminator" character varying(21) NOT NULL,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

CREATE TABLE public."AspNetUserClaims" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "UserId" TEXT NOT NULL,
    "ClaimType" TEXT,
    "ClaimValue" TEXT,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id")
);

CREATE TABLE public."AspNetUserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey")
);

CREATE TABLE public."AspNetUsers" (
    "Id" text NOT NULL DEFAULT (gen_random_uuid()),
    "ParticipantId" uuid NOT NULL,
    "UserName" text,
    "NormalizedUserName" text,
    "Email" text,
    "NormalizedEmail" text,
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id")
);

CREATE TABLE public."AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name")
);

CREATE TABLE public."Client" (
    "ClientId" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "ClientName" text NOT NULL,
    "ClientLogoLocation" text NOT NULL,
    "ClientHelpContact" text NOT NULL,
    "ClientIsActive" boolean NOT NULL,
    "ClientEmailDomain" text,
    CONSTRAINT "PK_Client" PRIMARY KEY ("ClientId")
);

CREATE TABLE public."DataProtectionKeys" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FriendlyName" text NOT NULL,
    "Xml" text NOT NULL,
    CONSTRAINT "PK_DataProtectionKeys" PRIMARY KEY ("Id")
);

CREATE TABLE public."EmailQueue" (
    "EmailQueueId" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1000),
    "ParticipantId" uuid NOT NULL,
    "EvaluationRateeId" uuid NOT NULL,
    "ClientId" uuid NOT NULL,
    "EmailActor" text NOT NULL,
    "EmailQueuedDateTime" timestamp with time zone NOT NULL,
    "EmailTest" boolean NOT NULL DEFAULT TRUE,
    "EmailFrom" text NOT NULL,
    "EmailTo" text NOT NULL,
    "EmailSubject" text NOT NULL,
    "EmailBodyHTML" text NOT NULL,
    "EmailBodyText" text NOT NULL,
    "EmailSent" boolean NOT NULL DEFAULT FALSE,
    "EmailSentDateTime" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EmailQueue" PRIMARY KEY ("EmailQueueId")
);

CREATE TABLE public."EvaluationParticipantStatus" (
    "EvaluationParticipantStatusId" integer NOT NULL,
    "EvaluationParticipantStatusName" text NOT NULL,
    "OnReminderNewStatus" integer NOT NULL,
    "OnCompletionNewStatus" integer NOT NULL,
    "OnOptOutNewStatus" integer NOT NULL,
    "EvaluationParticipantStatusIsActive" integer NOT NULL,
    "EvaluationParticipantStatusIsComplete" integer NOT NULL,
    "EvaluationParticipantStatusDecoration" text NOT NULL,
    CONSTRAINT "PK_EvaluationParticipantStatus" PRIMARY KEY ("EvaluationParticipantStatusId")
);

CREATE TABLE public."EvaluationRateeStatus" (
    "EvaluationRateeStatusId" integer NOT NULL,
    "EvaluationRateeStatusName" text NOT NULL,
    "OnReminderNewStatus" integer NOT NULL,
    "OnCompletionNewStatus" integer NOT NULL,
    "OnOptOutNewStatus" integer NOT NULL,
    CONSTRAINT "PK_EvaluationRateeStatus" PRIMARY KEY ("EvaluationRateeStatusId")
);

CREATE TABLE public."ParticipantRole" (
    "ParticipantRoleId" integer NOT NULL,
    "ParticipantRoleName" text NOT NULL,
    CONSTRAINT "PK_ParticipantRole" PRIMARY KEY ("ParticipantRoleId")
);

CREATE TABLE public."AspNetUserRole" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    "Id" text DEFAULT (gen_random_uuid()),
    "LoginProvider" text,
    "Name" text,
    CONSTRAINT "PK_AspNetUserRole" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRole_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES public."AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE public."EmailTemplate" (
    "EmailTemplateId" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "ClientId" uuid NOT NULL,
    "EmailTemplateName" text NOT NULL,
    "EmailFromName" text NOT NULL,
    "EmailSubject" text NOT NULL,
    "EmailTemplateContent" text NOT NULL,
    CONSTRAINT "PK_EmailTemplate" PRIMARY KEY ("EmailTemplateId"),
    CONSTRAINT "FK_EmailTemplate_Client_ClientId" FOREIGN KEY ("ClientId") REFERENCES public."Client" ("ClientId") ON DELETE CASCADE
);

CREATE TABLE public."Evaluation" (
    "EvaluationId" integer NOT NULL,
    "EvaluationActive" boolean NOT NULL DEFAULT FALSE,
    "EvaluationName" text NOT NULL,
    "EvaluationFolder" text NOT NULL,
    "EvaluationHelpContact" text,
    "EvaluationMaxRaters" integer NOT NULL,
    "EvaluationOpenDate" timestamp with time zone,
    "EvaluationRateeDueDate" timestamp with time zone,
    "EvaluationRaterDueDate" timestamp with time zone,
    "EvaluationClientContact" text,
    "ClientId" uuid NOT NULL,
    CONSTRAINT "PK_Evaluation" PRIMARY KEY ("EvaluationId"),
    CONSTRAINT "FK_Client_Evaluation_ClientId" FOREIGN KEY ("ClientId") REFERENCES public."Client" ("ClientId") ON DELETE CASCADE
);

CREATE TABLE public."Participant" (
    "ParticipantId" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "ParticipantNameFirst" text NOT NULL,
    "ParticipantNameLast" text NOT NULL,
    "ParticipantEmail" text NOT NULL,
    "ClientId" uuid NOT NULL,
    "ParticipantHasRegistered" boolean NOT NULL DEFAULT FALSE,
    "ParticipantIsActive" boolean NOT NULL,
    CONSTRAINT "PK_Participant" PRIMARY KEY ("ParticipantId"),
    CONSTRAINT "FK_Participant_Client_ClientId" FOREIGN KEY ("ClientId") REFERENCES public."Client" ("ClientId") ON DELETE CASCADE
);

CREATE TABLE public."EvaluationRatee" (
    "EvaluationRateeId" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "EvaluationId" integer NOT NULL,
    "ParticipantId" uuid NOT NULL,
    "EvaluationRateeStatusId" integer NOT NULL,
    "EvaluationRateeDueDateOverride" timestamp with time zone,
    "EvaluationRaterDueDateOverride" timestamp with time zone,
    "EvaluationRateeDateAdded" timestamp with time zone,
    CONSTRAINT "PK_EvaluationRatee" PRIMARY KEY ("EvaluationRateeId"),
    CONSTRAINT "FK_EvaluationRatee_EvaluationRateeStatus" FOREIGN KEY ("EvaluationRateeStatusId") REFERENCES public."EvaluationRateeStatus" ("EvaluationRateeStatusId"),
    CONSTRAINT "FK_EvaluationRatee_Evaluation_EvaluationId" FOREIGN KEY ("EvaluationId") REFERENCES public."Evaluation" ("EvaluationId") ON DELETE CASCADE,
    CONSTRAINT "FK_EvaluationRatee_Participant_ParticipantId" FOREIGN KEY ("ParticipantId") REFERENCES public."Participant" ("ParticipantId") ON DELETE CASCADE
);

CREATE TABLE public."EvaluationParticipant" (
    "EvaluationRateeId" uuid NOT NULL,
    "ParticipantId" uuid NOT NULL,
    "ParticipantRoleId" integer,
    "EvaluationParticipantSurveyPassword" text NOT NULL,
    "EvaluationParticipantDateLastEmailed" timestamp with time zone,
    "EvaluationParticipantStatusId" integer,
    "EvaluationParticipantDateAdded" timestamp with time zone NOT NULL,
    "EvaluationParticipantSessionId" text,
    "EvaluationParticipantDateCompleted" timestamp with time zone,
    CONSTRAINT "PK_EvaluationParticipant" PRIMARY KEY ("EvaluationRateeId", "ParticipantId"),
    CONSTRAINT "FK_EvaluationParticipant_EvaluationParticipantStatus" FOREIGN KEY ("EvaluationParticipantStatusId") REFERENCES public."EvaluationParticipantStatus" ("EvaluationParticipantStatusId"),
    CONSTRAINT "FK_EvaluationParticipant_EvaluationRatee" FOREIGN KEY ("EvaluationRateeId") REFERENCES public."EvaluationRatee" ("EvaluationRateeId") ON DELETE CASCADE,
    CONSTRAINT "FK_EvaluationParticipant_ParticipantRole_ParticipantRoleId" FOREIGN KEY ("ParticipantRoleId") REFERENCES public."ParticipantRole" ("ParticipantRoleId"),
    CONSTRAINT "FK_EvaluationParticipant_Participant_ParticipantId" FOREIGN KEY ("ParticipantId") REFERENCES public."Participant" ("ParticipantId") ON DELETE CASCADE
);

CREATE INDEX "IX_AspNetUserClaims_UserId" ON public."AspNetUserClaims" ("UserId");

CREATE INDEX "IX_EmailTemplate_ClientId" ON public."EmailTemplate" ("ClientId");

CREATE INDEX "IX_Evaluation_ClientId" ON public."Evaluation" ("ClientId");

CREATE INDEX "IX_EvaluationParticipant_EvaluationParticipantStatusId" ON public."EvaluationParticipant" ("EvaluationParticipantStatusId");

CREATE INDEX "IX_EvaluationParticipant_ParticipantId" ON public."EvaluationParticipant" ("ParticipantId");

CREATE INDEX "IX_EvaluationParticipant_ParticipantRoleId" ON public."EvaluationParticipant" ("ParticipantRoleId");

CREATE INDEX "IX_EvaluationRatee_EvaluationRateeStatusId" ON public."EvaluationRatee" ("EvaluationRateeStatusId");

CREATE INDEX "IX_EvaluationRatee_ParticipantId" ON public."EvaluationRatee" ("ParticipantId");

CREATE UNIQUE INDEX "UK_EvaluationRatee_EvaluationId_ParticipantId" ON public."EvaluationRatee" ("EvaluationId", "ParticipantId");

CREATE INDEX "IX_Participant_ClientId" ON public."Participant" ("ClientId");

CREATE UNIQUE INDEX "UK_Participant_ParticipantEmail" ON public."Participant" ("ParticipantEmail");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('00000000000000_CreateSchema', '9.0.8');


                CREATE OR REPLACE VIEW public."vwAdminParticipants" AS
                WITH er AS (
                SELECT
                    er_1."ParticipantId",
                    e_1."EvaluationId",
                    e_1."EvaluationActive"
                FROM
                    "EvaluationRatee" er_1
                JOIN "Evaluation" e_1
                    ON er_1."EvaluationId" = e_1."EvaluationId"
                ),
                ep AS (
                SELECT
                    ep_1."ParticipantId",
                    e_2."EvaluationId",
                    e_2."EvaluationActive",
                    ep_1."EvaluationParticipantDateLastEmailed"
                FROM
                    "EvaluationRatee" er_2
                JOIN "EvaluationParticipant" ep_1
                    ON er_2."EvaluationRateeId" = ep_1."EvaluationRateeId"
                JOIN "Evaluation" e_2
                    ON er_2."EvaluationId" = e_2."EvaluationId"
                ), 
                p AS (
                SELECT 
                    DISTINCT ON (p."ParticipantId")
                    c."ClientId",
                    c."ClientName",
                    p."ParticipantId", 
                    p."ParticipantNameFirst", 
                    p."ParticipantNameLast", 
                    p."ParticipantEmail",
                    p."ParticipantIsActive", 
                    CASE 
                        WHEN er."ParticipantId" IS NOT NULL THEN 'Yes' 
                        ELSE '' END "IsRatee", 
                    CASE 
                        WHEN p."ParticipantIsActive" THEN '' 
                        ELSE 'No' END "IsActive", 
                    ep."EvaluationParticipantDateLastEmailed" 
                FROM 
                                public."Client" c
                    INNER JOIN  public."Participant" p 
                    ON          c."ClientId" = p."ClientId"
                    LEFT JOIN er
                    ON p."ParticipantId" = er."ParticipantId"
                    LEFT JOIN ep
                    ON p."ParticipantId" = ep."ParticipantId"
                    ORDER BY 
                    p."ParticipantId",
                    ep."EvaluationParticipantDateLastEmailed" DESC)
                    SELECT
                    p."ClientId",
                    p."ClientName",
                    p."ParticipantId",
                    p."ParticipantNameFirst",
                    p."ParticipantNameLast",
                    p."ParticipantEmail",
                    p."ParticipantIsActive",
                    p."IsRatee",
                    p."IsActive",
                    p."EvaluationParticipantDateLastEmailed"
                    FROM p
                    ORDER BY p."ParticipantNameFirst", p."ParticipantNameLast"
                    ;


              CREATE OR REPLACE VIEW public."vwAdminRatees" AS
              WITH ar AS (
                SELECT
                    DISTINCT ON (p."ParticipantId")
                    c."ClientId",
                    c."ClientName",
                    e."EvaluationId",
                    p."ParticipantId", 
                    p."ParticipantNameFirst", 
                    p."ParticipantNameLast", 
                    p."ParticipantEmail", 
                    p."ParticipantIsActive",
                    er."EvaluationRateeDateAdded",
                    ep."EvaluationParticipantDateLastEmailed",
                    COALESCE(   "EvaluationRateeDueDateOverride", 
                                "EvaluationRateeDueDateOverride", 
                                "EvaluationRaterDueDate", 
                                "EvaluationRateeDueDate") as "LastDueDate"
                FROM 
                                public."Client" c
                    INNER JOIN  public."Evaluation" e
                    ON      c."ClientId" = e."ClientId"
                    INNER JOIN  public."EvaluationRatee" er 
                    ON      e."EvaluationId" = er."EvaluationId"
                    INNER JOIN  public."EvaluationParticipant" ep
                    ON      er."EvaluationRateeId" = ep."EvaluationRateeId"
                    AND     er."ParticipantId" = ep."ParticipantId"
                    INNER JOIN  public."Participant" p 
                    ON     er."ParticipantId" = p."ParticipantId"
                WHERE
                    e."EvaluationActive" = TRUE AND
                    p."ParticipantIsActive" = TRUE
                ORDER BY 
                    p."ParticipantId",
                    e."EvaluationRateeDueDate" DESC )
                SELECT
                    ar."ClientId",
                    ar."ClientName",
                    ar."EvaluationId",
                    ar."ParticipantId",
                    ar."ParticipantNameFirst",
                    ar."ParticipantNameLast",
                    ar."ParticipantEmail",
                    ar."ParticipantIsActive",
                    ar."EvaluationRateeDateAdded",
                    ar."EvaluationParticipantDateLastEmailed",
                    ar."LastDueDate"
                FROM ar
                ORDER BY
                    ar."ParticipantNameLast",
                    ar."ParticipantNameFirst";


                CREATE OR REPLACE VIEW public."vwRatersByRatee" AS
                SELECT 
                    er."EvaluationRateeId",
                    p."ParticipantId" AS "Ratee",
                    e."EvaluationId",
                    e."EvaluationActive",
                    e."EvaluationMaxRaters",
                    p2."ParticipantId", 
                    p2."ParticipantNameFirst", 
                    p2."ParticipantNameLast", 
                    p2."ParticipantEmail", 
                    pr."ParticipantRoleId",
                    pr."ParticipantRoleName",
                    ep."EvaluationParticipantDateLastEmailed",
                    eps."EvaluationParticipantStatusName",
                    eps."EvaluationParticipantStatusIsActive",
                    eps."EvaluationParticipantStatusIsComplete",
                    eps."EvaluationParticipantStatusDecoration"
                FROM 
                                public."Participant" p 
                    INNER JOIN  public."EvaluationRatee" er 
                    ON      p."ParticipantId" = er."ParticipantId" 
                    INNER JOIN  public."Evaluation" e
                    ON      er."EvaluationId" = e."EvaluationId"
                    INNER JOIN  public."EvaluationParticipant" ep 
                    ON      er."EvaluationRateeId" = ep."EvaluationRateeId" 
                    INNER JOIN  public."Participant" p2
                    ON      ep."ParticipantId" = p2."ParticipantId"
                    INNER JOIN  public."ParticipantRole" pr
                    ON      ep."ParticipantRoleId" = pr."ParticipantRoleId"
                    INNER JOIN  public."EvaluationParticipantStatus" eps
                    ON      ep."EvaluationParticipantStatusId" = eps."EvaluationParticipantStatusId"
                WHERE
                    p2."ParticipantIsActive" = TRUE
                ORDER BY    
                    p."ParticipantEmail" ASC,
                    pr."ParticipantRoleId" ASC,
                    p2."ParticipantNameLast" ASC,
                    p2."ParticipantNameFirst" ASC;


                CREATE OR REPLACE VIEW public."vwEvaluationsToComplete" AS
                SELECT 
                    p."ParticipantId" AS "Rater",
                    p."ParticipantNameFirst" AS "RaterNameFirst",
                    p."ParticipantNameLast" AS "RaterNameLast",
                    p."ParticipantEmail" AS "RaterEmail",
                    e."EvaluationId",
                    e."EvaluationActive",
                    e."EvaluationName",
                    e."EvaluationFolder",
                    ep."EvaluationParticipantSurveyPassword",
                    p2."ParticipantId", 
                    p2."ParticipantNameFirst", 
                    p2."ParticipantNameLast", 
                    p2."ParticipantEmail",
                    er."EvaluationRateeId",
                    pr."ParticipantRoleId",
                    pr."ParticipantRoleName",
                    ep."EvaluationParticipantDateLastEmailed",
                    COALESCE(er."EvaluationRateeDueDateOverride", er."EvaluationRateeDueDateOverride", e."EvaluationRaterDueDate") AS "DueDate",
                    eps."EvaluationParticipantStatusName",
                    eps."EvaluationParticipantStatusIsActive",
                    eps."EvaluationParticipantStatusIsComplete", 
                    eps."EvaluationParticipantStatusDecoration"
                FROM 
                                public."Evaluation" e
                    INNER JOIN  public."EvaluationRatee" er 
                    ON      e."EvaluationId" = er."EvaluationId"
                    INNER JOIN  public."EvaluationParticipant" ep 
                    ON      er."EvaluationRateeId" = ep."EvaluationRateeId"
                    INNER JOIN  public."Participant" p 
                    ON      ep."ParticipantId" = p."ParticipantId"
                    INNER JOIN  public."Participant" p2
                    ON      er."ParticipantId" = p2."ParticipantId"
                    INNER JOIN  public."ParticipantRole" pr
                    ON      ep."ParticipantRoleId" = pr."ParticipantRoleId"
                    INNER JOIN  public."EvaluationParticipantStatus" eps
                    ON      ep."EvaluationParticipantStatusId" = eps."EvaluationParticipantStatusId"
                WHERE
                    p."ParticipantIsActive" = TRUE AND
                    p2."ParticipantIsActive" = TRUE AND
                    e."EvaluationActive" = TRUE
                ORDER BY    
                    p."ParticipantEmail" ASC,
                    pr."ParticipantRoleId" ASC,
                    p2."ParticipantNameLast" ASC,
                    p2."ParticipantNameFirst" ASC;


              WITH ar AS (
                SELECT
                    DISTINCT ON (p."ParticipantId")
                    c."ClientId",
                    c."ClientName",
                    e."EvaluationId",
                    p."ParticipantId", 
                    p."ParticipantNameFirst", 
                    p."ParticipantNameLast", 
                    p."ParticipantEmail", 
                    p."ParticipantIsActive",
                    er."EvaluationRateeDateAdded",
                    ep."EvaluationParticipantDateLastEmailed",
                    COALESCE(   "EvaluationRateeDueDateOverride", 
                                "EvaluationRateeDueDateOverride", 
                                "EvaluationRaterDueDate", 
                                "EvaluationRateeDueDate") as "LastDueDate"
                FROM 
                                public."Client" c
                    INNER JOIN  public."Evaluation" e
                    ON      c."ClientId" = e."ClientId"
                    INNER JOIN  public."EvaluationRatee" er 
                    ON      e."EvaluationId" = er."EvaluationId"
                    INNER JOIN  public."EvaluationParticipant" ep
                    ON      er."EvaluationRateeId" = ep."EvaluationRateeId"
                    AND     er."ParticipantId" = ep."ParticipantId"
                    INNER JOIN  public."Participant" p
                    ON     er."ParticipantId" = p."ParticipantId"
                WHERE
                    e."EvaluationActive" = TRUE AND
                    p."ParticipantIsActive" = TRUE
                ORDER BY p."ParticipantId" )
                SELECT
                    ar."ClientId",
                    ar."ClientName",
                    ar."EvaluationId",
                    ar."ParticipantId",
                    ar."ParticipantNameFirst",
                    ar."ParticipantNameLast",
                    ar."ParticipantEmail",
                    ar."ParticipantIsActive",
                    ar."EvaluationRateeDateAdded",
                    ar."EvaluationParticipantDateLastEmailed",
                    ar."LastDueDate"
                FROM ar
                ORDER BY
                    ar."ParticipantNameLast",
                    ar."ParticipantNameFirst";


                CREATE OR REPLACE VIEW "vwEvaluationsByRatee" AS
                SELECT  DISTINCT
                        e."EvaluationId",
                        e."EvaluationActive",
                        e."EvaluationName",
                        e."EvaluationFolder",
                        COALESCE(e."EvaluationHelpContact", '00000000-0000-0000-0000-000000000000') AS "EvaluationHelpContact",
                        e."EvaluationMaxRaters",
                        e."EvaluationOpenDate",
                        e."EvaluationRateeDueDate",
                        e."EvaluationRaterDueDate",
                        e."EvaluationClientContact",
                        e."ClientId",
                        ep."ParticipantId"
                FROM public."Evaluation" e
                INNER JOIN  public."EvaluationRatee" er
                ON      e."EvaluationId" = er."EvaluationId"
                INNER JOIN  public."EvaluationParticipant" ep
                ON      er."EvaluationRateeId" = ep."EvaluationRateeId";


                CREATE OR REPLACE VIEW public."vwReminders" AS
                SELECT 
                    c."ClientId",
                    c."ClientName",
                    c."ClientHelpContact",
                    e."EvaluationId",
                    er."EvaluationRateeId",
                    r."ParticipantId" AS "RateeParticipantId",
                    r."ParticipantNameFirst" as "RateeNameFirst",
                    r."ParticipantNameLast" as "RateeNameLast",
                    CONCAT(r."ParticipantNameLast", ', ', r."ParticipantNameFirst") as "RateeNameCombined",
                    r."ParticipantEmail" as "RateeEmail",
                    p."ParticipantId" AS "ParticipantId",
                    p."ParticipantNameFirst" as "ParticipantNameFirst",
                    p."ParticipantNameLast" as "ParticipantNameLast",
                    CONCAT(p."ParticipantNameLast", ', ', p."ParticipantNameFirst") as "ParticipantNameCombined",
                    p."ParticipantEmail" as "ParticipantEmail",
                    pr."ParticipantRoleName",
                    'Reminder - General' AS "MessageToSend",
                    ep."EvaluationParticipantDateAdded",
                    ep."EvaluationParticipantDateLastEmailed",
                    COALESCE(   er."EvaluationRateeDueDateOverride", 
                                er."EvaluationRateeDueDateOverride", 
                                e."EvaluationRaterDueDate", 
                                e."EvaluationRateeDueDate") as "DueDate"
                FROM 
                                public."Client" c
                    INNER JOIN  public."Evaluation" e
                    ON      c."ClientId" = e."ClientId"
                    INNER JOIN  public."EvaluationRatee" er 
                    ON      e."EvaluationId" = er."EvaluationId"
                    INNER JOIN  public."EvaluationParticipant" ep
                    ON      er."EvaluationRateeId" = ep."EvaluationRateeId"
                    INNER JOIN  public."ParticipantRole" pr
                    ON      ep."ParticipantRoleId" = pr."ParticipantRoleId"
                    INNER JOIN  public."Participant" r
                    ON     er."ParticipantId" = r."ParticipantId"
                    INNER JOIN public."Participant" p
                    ON      ep."ParticipantId" = p."ParticipantId"
                    INNER JOIN public."EvaluationParticipantStatus" eps
                    ON      ep."EvaluationParticipantStatusId" = eps."EvaluationParticipantStatusId"
                WHERE eps."EvaluationParticipantStatusName" = 'Invitation Sent'
                    AND     e."EvaluationActive" = TRUE
                    AND     p."ParticipantIsActive" = TRUE
                    AND     r."ParticipantIsActive" = TRUE
                ORDER BY    
                    r."ParticipantNameLast",
                    r."ParticipantNameFirst",
                    p."ParticipantNameLast",
                    p."ParticipantNameFirst";


                CREATE OR REPLACE VIEW "vwParticipant" AS
                SELECT 
                            p."ParticipantId",
                            p."ParticipantNameFirst",
                            p."ParticipantNameLast",
                            p."ParticipantEmail",
                            COALESCE(anu."Email", p."ParticipantEmail") AS "Email",
                            p."ParticipantHasRegistered",
                            COALESCE(anu."EmailConfirmed", FALSE) AS "EmailConfirmed",
                            p."ParticipantIsActive",
                            COALESCE(anu."LockoutEnabled", FALSE) AS "LockoutEnabled",
                            COALESCE(anu."LockoutEnd", CURRENT_TIMESTAMP) AS "LockoutEnd",
                            COALESCE(anu."AccessFailedCount", -1) AS "AccessFailedCount"
                FROM 
                            public."Participant" p
                LEFT JOIN   public."AspNetUsers" anu
                ON          p."ParticipantEmail" = anu."Email";


                CREATE OR REPLACE VIEW public."vwDefaultEvaluationByParticipant" AS
                WITH er AS (
                    SELECT      er."ParticipantId",
                                er."EvaluationId",
                                e."EvaluationActive"
                    FROM        public."EvaluationRatee" er 
                    INNER JOIN  public."Evaluation" e
                    ON      er."EvaluationId" = e."EvaluationId"
                )
                SELECT 
                    DISTINCT ON (p."ParticipantId")
                    p."ParticipantId",
                    COALESCE(er."EvaluationId", 0) "EvaluationId",
                    COALESCE(er."EvaluationActive", false) "EvaluationActive"
                FROM 
                                public."Participant" p 
                    LEFT JOIN   er
                    ON      p."ParticipantId" = er."ParticipantId"
                ORDER BY    
                    p."ParticipantId" ASC,
                    er."EvaluationActive" DESC,
                    er."EvaluationId" DESC;


                CREATE OR REPLACE VIEW public."vwRaterInvitations" AS
                SELECT 	
                        ratee."ParticipantNameFirst" 	AS "RateeFirstName", 
                        ratee."ParticipantNameLast" 	AS "RateeLastName", 
                        vEC."ParticipantRoleName"		AS "RaterRole", 
                        rater."ParticipantNameFirst"	AS "RaterFirstName", 
                        rater."ParticipantNameLast"	AS "RaterLastName", 
                        rater."ParticipantEmail"		AS "RaterEmail",
                        rater."ParticipantId"         AS "RaterParticipantId",
                        vEC."DueDate"					AS "DueDate",
                        vEC."EvaluationRateeId"       AS "EvaluationRateeId",
                        c."ClientName"				AS "ClientName",
                        c."ClientId"					AS "ClientId",
                        c."ClientHelpContact"			AS "ClientHelpContact",
                        'Invitation - Rater'			AS "MessageToSend"
                FROM 		"vwEvaluationsToComplete" vEC
                INNER JOIN 	"Participant" ratee
                ON			vEC."ParticipantId" = ratee."ParticipantId"
                INNER JOIN 	"Participant" rater
                ON			vEC."Rater" = rater."ParticipantId"
                INNER JOIN	"Client" c
                ON			ratee."ClientId" = c."ClientId"
                WHERE 		"EvaluationParticipantDateLastEmailed" IS NULL
                AND         vEC."ParticipantRoleName" != 'Self'
                AND 		rater."ParticipantIsActive" = TRUE;


                CREATE OR REPLACE VIEW public."vwRateeInvitations" AS
                SELECT 	
                        ratee."ParticipantNameFirst" 	AS "RateeFirstName", 
                        ratee."ParticipantNameLast" 	AS "RateeLastName", 
                        vEC."ParticipantRoleName"		AS "RaterRole", 
                        rater."ParticipantNameFirst"	AS "RaterFirstName", 
                        rater."ParticipantNameLast"	AS "RaterLastName", 
                        rater."ParticipantEmail"		AS "RaterEmail",
                        rater."ParticipantId"         AS "RaterParticipantId",
                        vEC."DueDate"					AS "DueDate",
                        vEC."EvaluationRateeId"       AS "EvaluationRateeId",
                        c."ClientName"				AS "ClientName",
                        c."ClientId"					AS "ClientId",
                        c."ClientHelpContact"			AS "ClientHelpContact",
                        'Invitation - Ratee'			AS "MessageToSend"
                FROM 		"vwEvaluationsToComplete" vEC
                INNER JOIN 	"Participant" ratee
                ON			vEC."ParticipantId" = ratee."ParticipantId"
                INNER JOIN 	"Participant" rater
                ON			vEC."Rater" = rater."ParticipantId"
                INNER JOIN	"Client" c
                ON			ratee."ClientId" = c."ClientId"
                WHERE 		"EvaluationParticipantDateLastEmailed" IS NULL
                AND         vEC."ParticipantRoleName" = 'Self'
                AND 		rater."ParticipantIsActive" = TRUE;


                CREATE OR REPLACE FUNCTION
                public."fnEligibleRaters" (EvaluationRateeId uuid)
                RETURNS TABLE ( "EvaluationRateeId" uuid,
                                "ParticipantId" uuid, 
                                "ParticipantNameFirst" VARCHAR, 
                                "ParticipantNameLast" VARCHAR,
                                "ParticipantEmail" VARCHAR, 
                                "ParticipantHasRegistered" BOOLEAN)
                AS $func$
                WITH ep2 AS (
                    SELECT      p2."ParticipantId"
                    FROM        public."Participant" p2
                    INNER JOIN  public."EvaluationParticipant" ep
                    ON          p2."ParticipantId" = ep."ParticipantId"
                    AND         ep."EvaluationRateeId" = EvaluationRateeId
                )
                SELECT 
                            er."EvaluationRateeId",
                            p."ParticipantId",
                            p."ParticipantNameFirst",
                            p."ParticipantNameLast",
                            p."ParticipantEmail",
                            p."ParticipantHasRegistered"
                FROM        public."EvaluationRatee" er
                INNER JOIN  public."Participant" p2
                ON          er."ParticipantId" = p2."ParticipantId"
                AND         er."EvaluationRateeId" = EvaluationRateeId
                INNER JOIN  public."Participant" p
                ON          p2."ClientId" = p."ClientId"
                LEFT JOIN   ep2
                ON          p."ParticipantId" = ep2."ParticipantId"
                WHERE       p."ParticipantIsActive" = TRUE
                AND         ep2."ParticipantId" IS NULL
                ORDER BY    p."ParticipantNameLast", 
                            p."ParticipantNameFirst"
                $func$
                LANGUAGE sql;

